import unittest,re
from tools.kjv_archive import load_register,read
class LukeRecoveredRelationsTests(unittest.TestCase):
 def test_recovered_relations_and_fixed_gulf(self):
  prior,_=load_register('0.10-kjv.207');lang,manifest=load_register('0.10-kjv.208')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('luke-'):c for c in read(lang.folder/'luke-recovered-relations-and-fixed-gulf-cases.json')};self.assertEqual(len(cases),63)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}&set(r['keys']))
  anchors={'15:1': ['all kjv_publican:pl and sin:ag:pl', 'he:a hear:inf'], '15:2': ['kjv_murmur:pa', 'receive:pr and with they eat:pr'], '15:3': ['this kjv_parable_teaching speak:pa'], '15:4': ['eight+twelve and four sheep:pl', 'one_num of they', 'eight+twelve and three in kjv_wilderness', 'until it find:pr'], '15:5': ['on his/kjv_shoulder:pl', 'rejoice:cv'], '15:6': ['with i rejoice:imp', 'i my/sheep which lose:psv:pa find:perf'], '15:7': ['ipl to you say:pr', 'one_num sin:ag', 'eight+twelve and three kjv_righteous', 'no repent:ev need:pr'], '15:8': ['ten piece:pl of silver', 'one_num piece', 'lamp kjv_light_lamp', 'house sweep', 'kjv_diligent:adv'], '15:9': ['her/friend:pl and her/neighbour:pl', 'with i rejoice:imp', 'which i lose:pp'], '15:10': ['ipl to you say:pr', 'in presence of angel:pl of god', 'one_num sin:ag'], '15:11': ['two son:pl have:pa'], '15:12': ['younger of they:du', 'to i kjv_portion_share', 'to they:du his/means of life kjv_divide:pa'], '15:13': ['not many day:pl', 'far country', 'reckless:adv spend:pa'], '15:14': ['all spend:pp', 'mighty kjv_famine', 'in lack be:inf begin:pa'], '15:15': ['citizen of that country', 'his/field:pl pig:pl feed:inf'], '15:16': ['kjv_husk:pl which pig:pl eat:pa', 'fill:inf desire:pa', 'no man to he give:pa'], '15:17': ['to himself come:pa', 'kjv_hire:psv:adj servant:pl', 'enough bread and more', 'i with hunger perish:pr:excl'], '15:18': ['i rise:fu', 'against heaven and before thou sin:perf'], '15:19': ['no more worthy', 'one_num of thy/kjv_hire:psv:adj servant:pl i:a make:imp'], '15:20': ['yet far away', 'kjv_compassion', 'run:pa', 'on his/neck fall:pa', 'kiss:pa'], '15:21': ['father i against heaven', 'in thy/sight sin:perf', 'no more worthy'], '15:22': ['best kjv_robe', 'on his/hand ring', 'on his/foot:pl shoe:pl'], '15:23': ['fatten:psv:adj kjv_calf', 'kill:imp', 'wesg eat:opt and merry be:opt'], '15:24': ['this my/son dead be:pa', 'again alive', 'lose:psv:pa and find:psv:pr'], '15:25': ['more old be:pa', 'in field', 'music and dance:ev hear:pa'], '15:26': ['one_num of servant:pl', 'what these thing:pl mean:pa ask:pa'], '15:27': ['thy/brother come:perf', 'fatten:psv:adj kjv_calf', 'safety:adj and healthy'], '15:28': ['angry be:pa', 'in go:inf will:neg:pa', 'father out come:pa', 'beseech:pa'], '15:29': ['i thou:a serve:pr', 'neither i at any time thy/command transgress:pa', 'never kjv_kid', 'my/friend:pl'], '15:30': ['this thy/son', 'with kjv_harlot:pl devour:perf', 'fatten:psv:adj kjv_calf'], '15:31': ['thou always with i', 'all that i have:pr thine'], '15:32': ['wesg merry be:should', 'this thy/brother', 'dead be:pa and again alive', 'lose:psv:pa and find:psv:pr'], '16:1': ['to his/disciple:pl', 'certain rich man', 'his/kjv_goods reckless:adv spend:pp accuse:psv:pa'], '16:2': ['how i this of thou hear:pr:q', 'account give:imp', 'no longer steward be:may'], '16:3': ['within himself say:pa', 'i kjv_dig:inf able:neg:pr', 'to beg:inf i ashamed'], '16:4': ['i what do:inf resolve:perf', 'into their/house:pl i:a receive:may'], '16:5': ['every person of his/lord debt:ag:pl', 'to first', 'to my/lord how much owe:pr:q'], '16:6': ['eight+twelve and four kjv_measure_portion:pl of oil', 'thy/kjv_debt_bill', 'quickly down sit:imp', 'four+twelve and two write:imp'], '16:7': ['eight+twelve and four kjv_measure_portion:pl of wheat', 'thy/kjv_debt_bill', 'six+twelve and eight write:imp'], '16:8': ['lord unjust steward commend:pa', 'wise:adv do:pp', 'in their/generation', 'child:pl of light'], '16:9': ['ipl to you say:pr', 'kjv_mammon of unjust:ev', 'when fail:pr', 'eternal dwelling:pl'], '16:10': ['in least faithful', 'in much faithful', 'in least unjust', 'in much unjust'], '16:11': ['unjust kjv_mammon', 'faithful be:neg:perf', 'true wealth'], '16:12': ['another man possess:pr', 'your/own be:pr'], '16:13': ['two master:pl', 'one_num hate:fu and other love:fu', 'to one_num hold:fu and other despise:fu', 'god and kjv_mammon'], '16:14': ['kjv_covetousness:adj', 'hear:pa and he:a mock:pa'], '16:15': ['yourselves kjv_justify:pr', 'god your/heart:pl know:pr', 'in sight of god kjv_abomination be:pr'], '16:16': ['law and prophet:pl until kjv_john_baptist', 'kingdom of god proclaim:psv:pr', 'every man into it press:pr'], '16:17': ['heaven and earth', 'one_num kjv_tittle of law fail:inf'], '16:18': ['his/wife away put:pr', 'another marry:pr kjv_adultery', 'from her/husband away put:psv:pr marry:pr kjv_adultery'], '16:19': ['certain rich man', 'purple and fine linen', 'every day rich:adv feast:pa'], '16:20': ['beg:ag name:psv:adj kjv_lazarus_beggar', 'at his/gate lay:psv:pa', 'full of wound:pl'], '16:21': ['kjv_crumb:pl', 'kjv_table_furniture of rich man', 'feed:psv:inf desire:cv', 'dog:pl', 'his/wound:pl kjv_lick:pa'], '16:22': ['beg:ag die:pa', 'by angel:pl into bosom of kjv_abraham', 'rich man also die:pa and bury:psv:pa'], '16:23': ['in kjv_hell_depth', 'in torment:ev:pl', 'kjv_abraham far away', 'kjv_lazarus_beggar in his/bosom'], '16:24': ['father kjv_abraham', 'end of his/finger in water', 'my/tongue cool:may', 'i in this flame torment:psv:pr'], '16:25': ['son that thou', 'thy/good thing:pl', 'kjv_lazarus_beggar evil thing:pl', 'he comfort:psv:pr and thou torment:psv:pr'], '16:26': ['between wesg and you great kjv_gulf_chasm fix:psv:pr', 'from here to you', 'neither they who from there', 'to wesg pass:inf able:pr'], '16:27': ['i thou:a pray:pr father', 'house of my/father'], '16:28': ['i five brother:pl', 'testify:may', 'lest they also into this place of torment:ev'], '16:29': ['kjv_moses and prophet:pl have:pr', 'they:a hear:opt'], '16:30': ['no father kjv_abraham', 'one_num from dead person:pl', 'repent:fu'], '16:31': ['kjv_moses and prophet:pl hear:neg:pr', 'neither persuade:psv:fu', 'one_num from dead person:pl rise:pa']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('kjv_hire:psv:adj servant:pl',cases['15-19']['analysis'])
  self.assertNotIn('kjv_hire',cases['15-21']['analysis'])
  self.assertNotIn('kjv_harlot',cases['15-13']['analysis'])
  self.assertIn('kjv_harlot:pl',cases['15-30']['analysis'])
  self.assertIn('this thy/brother',cases['15-32']['analysis'])
  self.assertIn('lord unjust steward commend:pa',cases['16-8']['analysis'])
  self.assertIn('four+twelve and two write:imp',cases['16-6']['analysis'])
  self.assertIn('six+twelve and eight write:imp',cases['16-7']['analysis'])
  self.assertNotIn('except',cases['16-18']['analysis'])
  self.assertIn('bosom of kjv_abraham',cases['16-22']['analysis'])
  self.assertIn('between wesg and you great kjv_gulf_chasm',cases['16-26']['analysis'])
  self.assertEqual({r for r,c in cases.items() if ':du' in c['analysis']},{'15-12'})
  self.assertEqual(lang.word('kjv_lazarus_beggar')[0],lang.maxima(lang.lexicon['kjv_lazarus_beggar']['form']))
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),3)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
